{"source":"#include <stdio.h>
#include <math.h>
#define PI 3.141592654
int main(int argc, char *argv[])
{
    int n;
    float r,R;
    scanf("%d %f %f",&n,&R,&r);
    if(r==R){
        if(n==1) printf("YES\n");
        else printf("NO\n");
    }
    else{
         float s=asin(r/(R-r));
         float S=(s*180)/PI;
         if(n<=(180/S)) printf("YES\n");
         else printf("NO\n");
    }
    return 0;
}"}
